'use client';

import { useCallback, useEffect, useRef } from 'react';
import { freshKeyState, keyForSubmit, payloadFingerprint, type KeyState } from './idempotency-key';

/**
 * One Idempotency-Key per submission attempt, held in a ref (never regenerated by a re-render).
 * Created once on mount; reused when the same payload is resubmitted after a failure; replaced
 * when the payload changes after a failure, and after a success.
 */
export function useIdempotencyKey() {
  const state = useRef<KeyState | null>(null);

  useEffect(() => {
    state.current ??= freshKeyState();
  }, []);

  /** Returns the key to send with this payload. */
  const keyFor = useCallback(
    (payload: { domain: string; provider: string; mailboxCount: number }) => {
      state.current = keyForSubmit(state.current ?? freshKeyState(), payloadFingerprint(payload));
      return state.current.key;
    },
    [],
  );

  /** Call after a successful create, or when the server says the key no longer matches. */
  const renew = useCallback(() => {
    state.current = freshKeyState();
  }, []);

  return { keyFor, renew };
}
